def analyze_transcription(segments, min_duration=30, max_duration=60):
    print("Analisando Conversas…")
    conversation_segments = []
    current_segment = "" 
    current_start = None
    current_end = None

    for segment in segments:
        text = segment['text']
        start = segment['start']
        end = segment['end']
        duration = end - start

