                if len(current_segment) > 0 and (min_duration <= (current_end - current_start) <= max_duration):
                    conversation_segments.append({
                        'text': current_segment.strip(),
                        'start': current_start,
                        'end': current_end
                    })
                current_segment = text
                current_start = start
                current_end = end
            else:
                current_segment += f" {text}"
                current_end = end

            if (current_end - current_start) >= max_duration:
