                    conversation_segments.append({
                        'text': current_segment.strip(),
                        'start': current_start,
                        'end': current_end
                    })
                current_segment = "" 
                current_start = None
                current_end = None

    if len(current_segment) > 0 and (min_duration <= (current_end - current_start) <= max_duration):
        conversation_segments.append({
            'text': current_segment.strip(),
            'start': current_start,
            'end': current_end
        })

    print(f"Identificadas {len(conversation_segments)} Conversas Analizadas.")
    return conversation_segments

def manual_cut(segments, cut_duration_seconds):
    def is_end_of_sentence(text):
        return any(punct in text for punct in [".", "!", "?", ","])

    conversation_segments = []
    current_segment = ""
    current_start = None
    current_duration = 0

    for segment in segments:
        text = segment['text']
        start = segment['start']
        end = segment['end']
        duration = end - start

        if current_start is None:
            current_start = start

        if current_segment:
            current_segment += " "

        current_segment += text
        current_duration += duration

        if current_duration >= cut_duration_seconds and is_end_of_sentence(text):
            conversation_segments.append({
                'text': current_segment.strip(),
                'start': current_start,
                'end': end
            })
            current_segment = ""
            current_start = None
            current_duration = 0

    if current_segment:
        conversation_segments.append({
            'text': current_segment.strip(),
            'start': current_start,
            'end': end
        })

    return conversation_segments

